// Test-only stub for the two @deepseek-ai/dsh-util-values helpers used by the
// vendored JSON Schema validator: `assertNever` and `isJsonValue`.
export function assertNever(value, label = 'value') {
  throw new Error(`unexpected ${label}: ${String(value)}`);
}

export function isJsonValue(value, seen = new Set()) {
  if (value === null) return true;
  const type = typeof value;
  if (type === 'string' || type === 'boolean') return true;
  if (type === 'number') return Number.isFinite(value);
  if (type !== 'object') return false;
  if (seen.has(value)) return false;
  seen.add(value);
  let ok = true;
  if (Array.isArray(value)) {
    for (const item of value) {
      if (!isJsonValue(item, seen)) { ok = false; break; }
    }
  } else {
    const proto = Object.getPrototypeOf(value);
    if (proto !== Object.prototype && proto !== null) ok = false;
    else {
      for (const item of Object.values(value)) {
        if (!isJsonValue(item, seen)) { ok = false; break; }
      }
    }
  }
  seen.delete(value);
  return ok;
}

export default { assertNever, isJsonValue };
